    public Object parseOrder(Object order, Map<String, Object> market)
    {
        //
        // fetchOpenOrders
        //   [
        //     {
        //       "order_id": 315979358,
        //       "client_order_id": "add9a4b5-c7f7-4124-b57f-86982d86d479",
        //       "symbol": "ASTER",
        //       "side": "ask",
        //       "price": "1.836",
        //       "initial_amount": "85.33",
        //       "filled_amount": "0",
        //       "cancelled_amount": "0",
        //       "stop_price": null,
        //       "order_type": "limit",
        //       "stop_parent_order_id": null,
        //       "reduce_only": false,
        //       "created_at": 1759224706737,
        //       "updated_at": 1759224706737
        //     }
        //   ],
        //
        // fetchOrders
        //  [
        //     {
        //       "order_id": 315992721,
        //       "client_order_id": "ade",
        //       "symbol": "XPL",
        //       "side": "ask",
        //       "initial_price": "1.0865",
        //       "average_filled_price": "0",
        //       "amount": "984",
        //       "filled_amount": "0",
        //       "order_status": "open",
        //       "order_type": "limit",
        //       "stop_price": null,
        //       "stop_parent_order_id": null,
        //       "reduce_only": false,
        //       "reason": null,
        //       "created_at": 1759224893638,
        //       "updated_at": 1759224893638
        //     },
        //  ]
        //
        // fetchOrder
        //     {
        //       "history_id": 641452639,
        //       "order_id": 315992721,
        //       "client_order_id": "ade1aa6...",
        //       "symbol": "XPL",
        //       "side": "ask",
        //       "price": "1.0865",
        //       "initial_amount": "984",
        //       "filled_amount": "0",
        //       "cancelled_amount": "984",
        //       "event_type": "cancel",
        //       "order_type": "limit",
        //       "order_status": "cancelled",
        //       "stop_price": null,
        //       "stop_parent_order_id": null,
        //       "reduce_only": false,
        //       "created_at": 1759224895038
        //     }
        //
        // websocket watchOrders
        //     {
        //       "i": 1559665358,
        //       "I": null,
        //       "u": "BrZp5bidJ3WUvceSq7X78bhjTfZXeezzGvGEV4hAYKTa",
        //       "s": "BTC",
        //       "d": "bid",
        //       "p": "89501",
        //       "ip": "89501",
        //       "lp": "89501",
        //       "a": "0.00012",
        //       "f": "0.00012",
        //       "oe": "fulfill_limit",
        //       "os": "filled",
        //       "ot": "limit",
        //       "sp": null,
        //       "si": null,
        //       "r": false,
        //       "ct": 1765017049008,
        //       "ut": 1765017219639,
        //       "li": 1559696133
        //     }
        //
        String marketId = this.safeString2(order, "symbol", "s");
        Map<String, Object> marketResolved = this.safeMarket(marketId, market, (String) null, (String) null);
        String symbol = (String) marketResolved.get("symbol");
        Long timestamp = (Long) this.safeInteger2(order, "created_at", "ct");
        String status = this.safeString2(order, "order_status", "os", "open"); // open if method is fetchOpenOrders
        String side = this.safeString(order, "side", "d");
        if (!java.util.Objects.equals(side, null))
        {
            side = (((java.util.Objects.equals(side, "bid")))) ? "buy" : "sell";
        }
        String totalAmount = this.safeString2(order, "initial_amount", "a");
        String filledAmount = this.safeString2(order, "filled_amount", "f");
        String remaining = Precise.stringSub(totalAmount, filledAmount);
        String average = this.safeString2(order, "average_filled_price", "p");
        String eventType = this.safeString(order, "event_type");
        boolean isFillEvent = this.inArray(eventType, new ArrayList<Object>(Arrays.asList("fulfill_market", "fulfill_limit")));
        if ((java.util.Objects.equals(average, null)) && isFillEvent)
        {
            average = this.safeString(order, "price"); // on a matching event price is the fill price
        }
        return this.safeOrder(Helpers.newMap(
            "info", order,
            "id", this.safeString2(order, "order_id", "i"),
            "clientOrderId", this.safeString2(order, "client_order_id", "I"),
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "lastTradeTimestamp", null,
            "lastUpdateTimestamp", this.safeInteger2(order, "updated_at", "ut"),
            "symbol", symbol,
            "type", this.parseOrderType((String) (this.safeStringLower2(order, "order_type", "ot"))),
            "timeInForce", null,
            "postOnly", null,
            "reduceOnly", this.safeBool2(order, "reduce_only", "r", (Object) null),
            "side", side,
            "price", this.safeString2(order, "price", "lp"),
            "triggerPrice", this.safeNumber2(order, "stop_price", "sp", (Object) null),
            "amount", totalAmount,
            "cost", null,
            "average", average,
            "filled", filledAmount,
            "remaining", remaining,
            "status", this.parseOrderStatus(status),
            "fee", null,
            "trades", null
        ), marketResolved);
    }

